"""Numerical reconciliation and evidence gates for the seven-arm Stage A freeze."""
from __future__ import annotations

import copy
import hashlib
import json
from dataclasses import dataclass
from pathlib import Path

from agent_harness_evals import claude_capacity
from agent_harness_evals.multilang_stage_a import CURRENT_CORPUS_PATH
from agent_harness_evals.research_budget import (
    WORKFLOW, STAGE_A_ACCOUNTS, STAGE_A_ARCHIVE_ACCOUNTS, STAGE_A_QUALIFICATION_WORKFLOWS)
from agent_harness_evals.research_contract import digest

ROOT = Path(__file__).resolve().parents[1]
# Scheduler statuses that will charge no further research work.
SETTLED = frozenset({"terminal", "unstarted"})
DISPOSITION = ROOT / "docs/evidence/claude-capacity-167-disposition.json"
CORPUS = ROOT / CURRENT_CORPUS_PATH


def capacity_evidence_identities():
    disposition = json.loads(DISPOSITION.read_text())
    return {name: 'sha256:' + hashlib.sha256((ROOT / name).read_bytes()).hexdigest()
            for name in disposition['evidence']}


def approval_identity(freeze):
    """Avoid a digest cycle while binding every numerical and execution input."""
    value = copy.deepcopy(freeze)
    value.pop("freeze_approval_digest", None)
    return digest(value)


def exposure(freeze, *, qualification_workflows):
    """Worst-case whole-attempt exposure, including retained qualification use."""
    from agent_harness_evals.stage_scheduler import account_reservation_demand
    accounts = {}
    for slot in freeze["schedule"]:
        for account, units in account_reservation_demand(
                freeze, slot["arm_id"], remaining_attempts=freeze["limits"]["attempts"]).items():
            accounts[account] = accounts.get(account, 0) + units
    attempts = len(freeze["schedule"]) * freeze["limits"]["attempts"]
    total = attempts + qualification_workflows
    return {"scheduled_slots": len(freeze["schedule"]), "attempts": attempts,
            "provider_workflows": accounts, "qualification_workflows": qualification_workflows,
            "research_aggregate": {k: v * total for k, v in WORKFLOW.items()},
            "agent_seconds": attempts * freeze["limits"]["workflow_seconds"]}


def remaining_research_demand(freeze, state, trial_used):
    """Whole workflows unsettled attempts may still charge, and in-flight work already charged.

    Research is charged to the shared `used` as it happens, in the same
    transaction as the attempt's `trial-work:<trial_id>` row. A finished
    attempt is therefore fully charged and not counted. Each unfinished or
    unstarted attempt of an unsettled slot counts one whole workflow. The one
    unfinished attempt of a slot with no finished attempt is credited with its
    trial row (`trial_used(trial_id)`, at most one workflow), because that row
    holds only its charges; any other in-flight charge is not attributable and
    is not credited. Without a scheduler state every scheduled attempt counts.
    """
    limit = freeze["limits"]["attempts"]
    credit = {k: 0 for k in WORKFLOW}
    if state is None:
        return len(freeze["schedule"]) * limit, credit
    workflows = 0
    for slot in state["slots"]:
        if slot["status"] in SETTLED:
            continue
        attempts = slot.get("attempts") or []
        finished = sum(attempt.get("finished_at") is not None for attempt in attempts)
        workflows += max(limit - finished, 0)
        if slot["status"] == "in_flight" and len(attempts) == 1 and finished == 0:
            charged = trial_used(slot["trial_id"])
            for k in WORKFLOW:
                credit[k] += max(0, min(charged.get(k, 0), WORKFLOW[k]))
    return workflows, credit


def _trial_used(connection, trial_id):
    row = connection.execute("SELECT value FROM state WHERE key=?", (f"trial-work:{trial_id}",)).fetchone()
    used = json.loads(row[0]).get("used", {}) if row else {}
    return {k: v for k, v in used.items() if type(v) is int}


